-- Phase 9 Part 3: one live broadcast per tutor (SPEC §4.6, §7.8; DECISIONS,
-- "Phase 9 Part 3").
--
-- GENERATED by `drizzle-kit generate` from src/db/schema/broadcast.ts; only this
-- comment is hand-written.
--
-- `startBroadcast` (lib/broadcasts/service.ts) locks the tutor's tutor_profiles
-- row and checks for a live broadcast before inserting, so two presses of "Go
-- live" serialize and the second is refused. This index is what makes a second
-- live row impossible for any writer, including one that skips that lock; the
-- adapter maps its 23505 to "You're already live".
--
-- Safe on production as-is: no client can write broadcasts (drizzle/0018) and no
-- server path created one before this part, so no tutor holds two live rows.
CREATE UNIQUE INDEX "broadcasts_one_live_per_tutor" ON "broadcasts" USING btree ("tutor_id") WHERE status = 'live';
